def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); centers=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v and v!=3 and all(0<=rr<h and 0<=cc<w and grid[rr][cc]==3 for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]): centers.append((r,c,v))
    for r,c,v in centers:
        for j in range(w):
            if grid[r][j]==0: out[r][j]=v
    for r,c,v in centers:
        for i in range(h):
            if grid[i][c]==0: out[i][c]=v
    return out

